from itertools import permutations

def is_costas(p):
    n = len(p)
    for dc in range(1, n):
        seen = set()
        for c in range(n - dc):
            dr = p[c+dc] - p[c]
            if dr in seen:
                return False
            seen.add(dr)
    return True

n = 12
fixed = {3: 8, 8: 2}
used = set(fixed.values())
cols = [c for c in range(n) if c not in fixed]
rows_avail = [r for r in range(n) if r not in used]

x = [0]*n
for c,r in fixed.items():
