from itertools import combinations

def find(n=7, maxlen=40):
    # x[0]=0, x[1]=2
    def rec(marks, used):
        if len(marks) == n:
            return marks
        last = marks[-1]
        for nxt in range(last+1, maxlen+1):
            new_d = set()
            ok = True
            for m in marks:
                d = nxt - m
                if d in used or d in new_d:
                    ok = False; break
                new_d.add(d)
            if ok:
                r = rec(marks+[nxt], used|new_d)
                if r: return r
        return None
    return rec([0,2], {2})

