import itertools
def girth_calc(G):
    g = float('inf')
    for v in G.nodes():
        # BFS
        dist = {v: 0}
        parent = {v: None}
        queue = [v]
        while queue:
            new_queue = []
            for u in queue:
                for w in G.neighbors(u):
                    if w not in dist:
                        dist[w] = dist[u]+1
                        parent[w] = u
                        new_queue.append(w)
                    elif parent[u] != w:
                        cycle_len = dist[u] + dist[w] + 1
                        if cycle_len < g:
                            g = cycle_len
            queue = new_queue
    return g

