from itertools import combinations

def girth(n, edges):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v); adj[v].append(u)
    best = float('inf')
    for src in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[src]=0
        from collections import deque
        q=deque([src])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]==-1:
                    dist[v]=dist[u]+1
                    parent[v]=u
                    q.append(v)
                elif parent[u]!=v:
                    c = dist[u]+dist[v]+1
                    if c<best: best=c
    return best

def chromatic_leq(n, edges, k):
    # try greedy + backtrack
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    color=[-1]*n
    order = sorted(range(n), key=lambda x:-len(adj[x]))
    def bt(i):
        if i==n: return True
        v=order[i]
        used=set(color[u] for u in adj[v] if color[u]!=-1)
        for c in range(k):
            if c not in used:
                color[v]=c
                if bt(i+1): return True
                color[v]=-1
        return False
    return bt(0)

