def neighbors(c):
    r,col=divmod(c,8)
    res=[]
    for dr,dc in [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]:
        nr,nc=r+dr,col+dc
        if 0<=nr<8 and 0<=nc<8:
            res.append(nr*8+nc)
    return res

