import random

def has_short_cycle(adj, n, max_len=5):
    # BFS from each vertex to find cycles of length <= max_len
    for s in range(n):
        # BFS tracking parent
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nq = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        if dist[v] < max_len:
                            nq.append(v)
                    elif v != parent[u]:
                        # found cycle of length dist[u]+dist[v]+1
                        if dist[u]+dist[v]+1 <= max_len:
                            return True
            queue = nq
    return False

def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        queue = [s]
        while queue:
            nq = []
            for u in queue:
                for v in adj[u]:
                    if dist[v] == -1:
                        dist[v] = dist[u]+1
                        parent[v] = u
                        nq.append(v)
                    elif parent[u] != v:
                        cyc = dist[u]+dist[v]+1
                        if cyc < g:
                            g = cyc
            queue = nq
    return g

